import java.util.concurrent.CountDownLatch;
import java.util.concurrent.TimeUnit;
import java.util.concurrent.atomic.AtomicBoolean;
import java.util.concurrent.atomic.AtomicInteger;
import java.util.concurrent.atomic.AtomicLong;

public class Harness {
    /** Every wait in this harness is bounded by this; the watchdog is the last resort. */
    private static final long DEADLINE_MS = 5_000L;
    private static final int KEYS = 8;

    public static void main(String[] args) {
        Atrophy.plan(2);
        Atrophy.watchdog(30000);
        try {
            perKeyTotals();
            concurrentIncrements();
        } catch (Throwable t) {
            Atrophy.check("harness crashed: " + t, false);
        } finally {
            Atrophy.report();
        }
    }

    private static Thread daemon(String name, Runnable body) {
        Thread t = new Thread(body, name);
        t.setDaemon(true);
        t.start();
        return t;
    }

    /** Check 1: counts are per key, and a key nobody touched reads 0. */
    private static void perKeyTotals() throws InterruptedException {
        Solution counter = new Solution();
        AtomicBoolean exact = new AtomicBoolean();
        AtomicInteger crashes = new AtomicInteger();
        CountDownLatch finished = new CountDownLatch(1);

        // One worker owns every call: main never touches Solution, so an unimplemented
        // method fails this check instead of unwinding out of the whole harness.
        daemon("single", () -> {
            try {
                for (int k = 0; k < KEYS; k++) {
                    for (int n = 0; n <= k; n++) counter.increment("k" + k);
                }
                boolean ok = counter.get("never-incremented") == 0L;
                for (int k = 0; k < KEYS; k++) {
                    if (counter.get("k" + k) != (long) (k + 1)) ok = false;
                }
                exact.set(ok);
            } catch (Throwable t) {
                crashes.incrementAndGet();
            } finally {
                finished.countDown();
            }
        });

        boolean drained = finished.await(DEADLINE_MS, TimeUnit.MILLISECONDS);
        Atrophy.check("per-key totals are exact and an untouched key reads 0",
                drained && crashes.get() == 0 && exact.get());
    }

    /** Check 2: 4 threads x 10000 increments over 8 keys land exactly - no lost updates. */
    private static void concurrentIncrements() throws InterruptedException {
        final int THREADS = 4;
        final int PER_THREAD = 10_000;
        final long PER_KEY = (long) THREADS * PER_THREAD / KEYS; // 5000
        Solution counter = new Solution();
        AtomicInteger crashes = new AtomicInteger();
        CountDownLatch finished = new CountDownLatch(THREADS);

        for (int t = 0; t < THREADS; t++) {
            daemon("bumper-" + t, () -> {
                try {
                    for (int i = 0; i < PER_THREAD; i++) counter.increment("k" + (i % KEYS));
                } catch (Throwable e) {
                    crashes.incrementAndGet();
                } finally {
                    finished.countDown();
                }
            });
        }
        boolean drained = finished.await(15, TimeUnit.SECONDS);

        // Read back on a worker too, and only after every bumper is done (the latch is the
        // happens-before edge), so the totals are settled and main still never calls Solution.
        AtomicLong total = new AtomicLong(-1);
        AtomicBoolean perKeyExact = new AtomicBoolean();
        CountDownLatch read = new CountDownLatch(1);
        boolean readBack = false;
        // Only once every bumper is done: it keeps the worker count at 4 even on the
        // pathological path, and the latch is the happens-before edge the read needs.
        if (drained) {
            daemon("reader", () -> {
                try {
                    long sum = 0;
                    boolean exact = true;
                    for (int k = 0; k < KEYS; k++) {
                        long v = counter.get("k" + k);
                        if (v != PER_KEY) exact = false;
                        sum += v;
                    }
                    perKeyExact.set(exact);
                    total.set(sum);
                } catch (Throwable e) {
                    crashes.incrementAndGet();
                } finally {
                    read.countDown();
                }
            });
            readBack = read.await(DEADLINE_MS, TimeUnit.MILLISECONDS);
        }

        boolean ok = drained
                && readBack
                && crashes.get() == 0
                && perKeyExact.get()
                && total.get() == (long) THREADS * PER_THREAD;
        Atrophy.check("40000 increments from 4 threads all land (5000 per key)", ok);
    }
}
